# SPDX-License-Identifier: MIT
# Independent bl-integrity manifest-v2 oracle (takeover root). Walks the given
# roots with lstat, hashes regular files with hashlib (sha256, blake2b-512),
# renders the documented rows, and checks captured emit/verify output.
import hashlib, os, stat, sys

DEFAULTS = ['/bin', '/bash-os', '/etc/bash-os']
HEADER = '# bl-integrity manifest v2\n# columns: type mode size sha256 blake2b uid gid mtime ctime target rel\n'


def walk(root, rel, out):
    full = os.path.join(root, rel)
    try:
        st = os.lstat(full)
    except FileNotFoundError:
        return
    if stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode):
        out.append(rel)
    elif stat.S_ISDIR(st.st_mode):
        for name in os.listdir(full):
            if '\n' not in name and '\t' not in name:
                walk(root, rel + '/' + name, out)


def row(root, rel):
    full = os.path.join(root, rel)
    st = os.lstat(full)
    mode = '%o' % (st.st_mode & 0o7777)
    if stat.S_ISLNK(st.st_mode):
        return '\t'.join(['symlink', mode] + ['-'] * 7 + [os.readlink(full), '/' + rel])
    data = open(full, 'rb').read()
    return '\t'.join(['file', mode, str(st.st_size), hashlib.sha256(data).hexdigest(),
                      hashlib.blake2b(data, digest_size=64).hexdigest(), str(st.st_uid), str(st.st_gid),
                      str(int(st.st_mtime)), str(int(st.st_ctime)), '-', '/' + rel])


def rows(root):
    paths = []
    for r in DEFAULTS:
        walk(root, r.lstrip('/'), paths)
    return [row(root, p) for p in sorted(paths, key=lambda p: p.encode())]


def main():
    cmd, root, label = sys.argv[1:4]
    if cmd == 'manifest':
        with open(label, 'w') as handle:
            handle.write(HEADER + '# root=%s\n' % root + ''.join(r + '\n' for r in rows(root)))
        return
    got = open('out.' + label).read()
    err = open('err.' + label).read()
    status = sys.argv[4]
    current = rows(root)
    if cmd == 'emit':
        want = HEADER + '# root=%s\n' % root + ''.join(r + '\n' for r in current)
        if label.endswith('noheader'):
            want = ''.join(r + '\n' for r in current)
        verdict = 'match' if got == want else 'differ'
    else:
        manifest = [l for l in open(sys.argv[5]).read().splitlines() if l and not l.startswith('#')]
        path = lambda r: r.split('\t', 10)[10]
        old = {path(r): r for r in manifest}
        new = {path(r): r for r in current}
        want = ''
        for r in manifest:
            p = path(r)
            if p not in new:
                want += 'missing\t%s\n' % p
            elif new[p] != r:
                want += 'changed\t%s\n' % p
        for r in current:
            if path(r) not in old:
                want += 'added\t%s\n' % path(r)
        verdict = 'match' if got == want else 'differ'
        print('%s report=%r' % (label, want))
    print('%s status=%s rows=%d %s stderr=%s' % (label, status, len(current), verdict, 'empty' if not err else 'text'))


main()

